import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));StringTokenizer st = new StringTokenizer(br.readLine());long n = Long.parseLong(st.nextToken());long m = Long.parseLong(st.nextToken());long minPairs = calculateMin(n, m);long maxPairs = calculateMax(n, m);System.out.println(minPairs + " " + maxPairs);}private static long calculateMin(long n, long m) {long base = n / m;long remainder = n % m;long pairs = remainder * combinations2(base + 1) + (m - remainder) * combinations2(base);return pairs;}private static long calculateMax(long n, long m) {long size = n - (m - 1);return combinations2(size);}private static long combinations2(long k) {if (k < 2) return 0;return k * (k - 1) / 2;}}